from drf_spectacular.utils import (
    extend_schema, extend_schema_view,
    OpenApiParameter, OpenApiTypes, OpenApiExample, OpenApiResponse,
)
from rest_framework import viewsets
from .models import Book
from .serializers import BookListSerializer, BookDetailSerializer, BookWriteSerializer


@extend_schema_view(
    list=extend_schema(
        summary="لیست کتاب‌ها",
        description="کتاب‌های منتشرشده با فیلتر، جستجو، مرتب‌سازی و صفحه‌بندی.",
        tags=["Books"],
        parameters=[
            OpenApiParameter(
                "category", OpenApiTypes.STR,
                description="اسلاگ دسته‌بندی",
                required=False,
            ),
            OpenApiParameter(
                "min_price", OpenApiTypes.DECIMAL,
                description="حداقل قیمت",
                required=False,
            ),
            OpenApiParameter(
                "max_price", OpenApiTypes.DECIMAL,
                description="حداکثر قیمت",
                required=False,
            ),
            OpenApiParameter(
                "in_stock", OpenApiTypes.BOOL,
                description="فقط کتاب‌های موجود",
                required=False,
            ),
            OpenApiParameter(
                "search", OpenApiTypes.STR,
                description="جستجو در عنوان، ISBN و نام نویسنده",
                required=False,
            ),
            OpenApiParameter(
                "ordering", OpenApiTypes.STR,
                description="مرتب‌سازی بر اساس: price, -price, created_at, published_at",
                required=False,
            ),
        ],
        examples=[
            OpenApiExample(
                "پاسخ نمونه",
                value={
                    "count": 137,
                    "next": "http://api/books/?page=2",
                    "previous": None,
                    "results": [
                        {
                            "id": 1,
                            "title": "Clean Code",
                            "author_name": "Robert C. Martin",
                            "price": "42.50",
                            "average_rating": 4.5,
                        }
                    ],
                },
                response_only=True,
            ),
        ],
    ),
    retrieve=extend_schema(
        summary="جزئیات کتاب",
        tags=["Books"],
        responses={
            200: BookDetailSerializer,
            404: OpenApiResponse(description="کتاب پیدا نشد"),
        },
    ),
    create=extend_schema(
        summary="ساخت کتاب جدید",
        tags=["Books"],
        request=BookWriteSerializer,
        responses={
            201: OpenApiResponse(description="کتاب ساخته شد"),
            400: OpenApiResponse(description="داده نامعتبر"),
            401: OpenApiResponse(description="احراز هویت لازم"),
        },
    ),
    update=extend_schema(tags=["Books"], summary="ویرایش کامل کتاب"),
    partial_update=extend_schema(tags=["Books"], summary="ویرایش جزئی"),
    destroy=extend_schema(tags=["Books"], summary="حذف کتاب"),
)
class BookViewSet(viewsets.ModelViewSet):
    queryset = Book.objects.select_related("author").all()

    def get_serializer_class(self):
        if self.action == "list":
            return BookListSerializer
        if self.action in ("create", "update", "partial_update"):
            return BookWriteSerializer
        return BookDetailSerializer

    @extend_schema(
        summary="کتاب‌های ویژه",
        description="۱۰ کتاب ویژه برای نمایش در صفحه اصلی.",
        tags=["Books"],
        responses={200: BookListSerializer(many=True)},
    )
    @action(detail=False, methods=["get"])
    def featured(self, request):
        books = self.get_queryset().filter(is_featured=True)[:10]
        serializer = self.get_serializer(books, many=True)
        return Response(serializer.data)

    @extend_schema(
        summary="تغییر وضعیت انتشار",
        tags=["Books"],
        request=None,
        responses={
            200: OpenApiResponse(
                description="وضعیت تغییر کرد",
                examples=[
                    OpenApiExample(
                        "پاسخ",
                        value={"id": 1, "is_published": True},
                    ),
                ],
            ),
        },
    )
    @action(detail=True, methods=["post"])
    def toggle_publish(self, request, pk=None):
        book = self.get_object()
        book.is_published = not book.is_published
        book.save(update_fields=["is_published"])
        return Response({"id": book.id, "is_published": book.is_published})


from rest_framework.decorators import action
from rest_framework.response import Response

from rest_framework import serializers
from .models import Book, Author, Category, Review


class AuthorMiniSerializer(serializers.ModelSerializer):
    class Meta:
        model = Author
        fields = ["id", "full_name"]


class CategoryMiniSerializer(serializers.ModelSerializer):
    class Meta:
        model = Category
        fields = ["id", "name", "slug"]


class BookSerializer(serializers.ModelSerializer):
    author = AuthorMiniSerializer(read_only=True)
    categories = CategoryMiniSerializer(many=True, read_only=True)
    reviews_count = serializers.IntegerField(read_only=True)
    average_rating = serializers.FloatField(read_only=True)

    class Meta:
        model = Book
        fields = [
            "id", "title", "author", "categories",
            "price", "reviews_count", "average_rating",
        ]

from django.db.models import Avg, Count, Prefetch, Q
from .models import Book, Category, Review


# ❌ نسخه کند — N+1
def slow_queryset():
    return Book.objects.filter(is_active=True)


# ✅ نسخه بهینه
def optimized_queryset():
    return (
        Book.objects
        .filter(is_active=True)
        .select_related("author")
        .prefetch_related(
            Prefetch(
                "categories",
                queryset=Category.objects.only("id", "name", "slug"),
            ),
        )
        .annotate(
            reviews_count=Count(
                "reviews",
                filter=Q(reviews__is_approved=True),
                distinct=True,
            ),
            average_rating=Avg(
                "reviews__rating",
                filter=Q(reviews__is_approved=True),
            ),
        )
        .only(
            "id", "title", "price", "author_id", "created_at",
        )
        .order_by("-created_at")
    )

